package com.modelrag.server.monitor;
import com.modelrag.common.dto.ApiResponse; import com.modelrag.common.metrics.TokenUsageTracker; import com.modelrag.common.security.AccessControlService; import com.modelrag.server.model.ModelClient; import com.modelrag.server.model.ModelHealthStore; import java.util.List; import java.util.Map; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/monitor") public class MonitorController {private final TokenUsageTracker tokens;private final AccessControlService access;private final ModelHealthStore models;private final List<ModelClient> clients;public MonitorController(TokenUsageTracker tokens,AccessControlService access,ModelHealthStore models,List<ModelClient> clients){this.tokens=tokens;this.access=access;this.models=models;this.clients=clients;}@GetMapping("/overview")public ApiResponse<TokenUsageTracker.Usage> overview(@RequestParam long datasetId){access.requireDatasetAccess(datasetId);return ApiResponse.success(tokens.usage(datasetId));}@GetMapping("/model-health")public ApiResponse<List<Map<String,Object>>> modelHealth(){access.requireRole("ADMIN");return ApiResponse.success(models.snapshot(clients));}@PutMapping("/model-candidates")public ApiResponse<Map<String,Object>> saveModelCandidate(@RequestBody Map<String,Object> body){access.requireRole("ADMIN");String type=String.valueOf(body.getOrDefault("modelType","CHAT"));String name=String.valueOf(body.getOrDefault("modelName",""));if(name.isBlank())throw new IllegalArgumentException("modelName 不能为空");String provider=String.valueOf(body.getOrDefault("provider","local"));int priority=body.get("priority") instanceof Number n?n.intValue():0;boolean enabled=!(body.get("enabled") instanceof Boolean b)||b;int canary=body.get("canaryPercent") instanceof Number n?n.intValue():0;return ApiResponse.success(models.saveCandidate(type,name,provider,priority,enabled,canary));}}
